const {getDefaultConfig} = require('@expo/metro-config')

const defaultConfig = getDefaultConfig(__dirname)

defaultConfig.resolver.sourceExts.push('cjs')

module.exports = defaultConfig

const fg = require('fast-glob')
const fs = require('fs')
const path = require('path')
const {Project} = require('ts-morph')

const aliasMap = {
  '@screens': 'src/screens',
  '@components': 'src/components',
  '@constants': 'src/constants',
  '@services': 'src/services',
  '@types': 'src/types',
  '@theme': 'src/styles',
  '@store': 'src/store',
  '@data': 'src/data',
  '@service': 'src/service'
}

const isLocalRelative = importPath => importPath.startsWith('./')
const isDeepRelative = importPath => importPath.startsWith('../')
const isThirdPartyImport = importPath => !importPath.startsWith('.') && !importPath.startsWith('@')

function getAliasPath(importPath, sourceFilePath) {
  if (!importPath.startsWith('..')) return null
  const absPath = path.resolve(path.dirname(sourceFilePath), importPath)

  for (const [alias, target] of Object.entries(aliasMap)) {
    const absTarget = path.resolve(target)

    if (absPath.startsWith(absTarget)) {
      const relative = path.relative(absTarget, absPath)

      return `${alias}/${relative.replace(/\\/g, '/')}`
    }
  }

  return null
}

function formatImportStructure(struct) {
  const namedImports = struct.namedImports || []
  const defaultImport = struct.defaultImport
  const namespaceImport = struct.namespaceImport
  const moduleSpecifier = `'${struct.moduleSpecifier}'`

  if (namespaceImport) {
    return `import * as ${namespaceImport} from ${moduleSpecifier}`
  }

  if (namedImports.length === 0) {
    return `import ${defaultImport} from ${moduleSpecifier}`
  }

  const names = namedImports.map(i => i.name)
  const named = `{${names.join(',')}}`

  if (defaultImport) {
    return `import ${defaultImport}, ${named} from ${moduleSpecifier}`
  }

  return `import ${named} from ${moduleSpecifier}`
}

const targetDirArg = process.argv[2]

if (!targetDirArg) {
  console.error('❌ Please provide a directory name, e.g., node script.js screens')
  process.exit(1)
}

const resolvedTarget = fg.sync([`**/${targetDirArg}`], {
  onlyDirectories: true,
  cwd: process.cwd(),
  absolute: true
})[0]

if (!resolvedTarget || !fs.existsSync(resolvedTarget)) {
  console.error(`❌ Could not find directory matching "${targetDirArg}"`)
  process.exit(1)
}

;(async () => {
  const files = await fg([`${resolvedTarget}/**/*.{ts,tsx,js,jsx}`], {dot: true})
  const project = new Project()

  files.forEach(file => project.addSourceFileAtPath(file))
  const sourceFiles = project.getSourceFiles()

  for (const file of sourceFiles) {
    const imports = file.getImportDeclarations()

    if (imports.length === 0) continue

    const reactImports = []
    const thirdPartyImports = []
    const aliasedImports = []
    const deepRelativeImports = []
    const localRelativeImports = []

    for (const imp of imports) {
      const module = imp.getModuleSpecifierValue()

      if (module === 'react') {
        reactImports.push(imp)
      } else if (isLocalRelative(module)) {
        localRelativeImports.push(imp)
      } else if (isDeepRelative(module)) {
        const alias = getAliasPath(module, file.getFilePath())

        if (alias) {
          imp.setModuleSpecifier(alias)
          aliasedImports.push(imp)
        } else {
          deepRelativeImports.push(imp)
        }
      } else if (isThirdPartyImport(module)) {
        thirdPartyImports.push(imp)
      } else {
        aliasedImports.push(imp)
      }
    }

    const sortByModule = (a, b) => a.getModuleSpecifierValue().localeCompare(b.getModuleSpecifierValue())

    const sortedGroups = [
      reactImports,
      thirdPartyImports.sort(sortByModule),
      aliasedImports.sort(sortByModule),
      deepRelativeImports.sort(sortByModule),
      localRelativeImports.sort(sortByModule)
    ]

    const formattedGroupStrings = sortedGroups
      .filter(group => group.length > 0)
      .map(group => group.map(imp => formatImportStructure(imp.getStructure())).join('\n'))

    const finalImportBlock = formattedGroupStrings.join('\n\n')
    const finalImportBlockTrimmed = finalImportBlock.trimEnd()

    const firstImport = imports[0]
    const lastImport = imports[imports.length - 1]
    const start = firstImport.getFullStart()
    const end = lastImport.getEnd()

    const fullText = file.getFullText()
    let remainingText = fullText.slice(end)

    const remainingLines = remainingText.split('\n')
    const firstLine = remainingLines.find(line => line.trim().length > 0)
    const isCodeLine = firstLine && /^[a-zA-Z0-9_]/.test(firstLine.trim())
    const spacer = isCodeLine && !remainingText.startsWith('\n') ? '\n' : ''

    const newText = fullText.slice(0, start) + finalImportBlockTrimmed + spacer + remainingText

    file.replaceWithText(newText)
    await file.save()
  }

  console.log(`✅ Imports reformatted in ${sourceFiles.length} files in directory "${targetDirArg}"`)
})()

import React, {useEffect, useState, useRef} from 'react'
import {ReactNode} from 'react'

import {Keyboard, View, TouchableWithoutFeedback} from 'react-native'

import BottomSheet, {BottomSheetView} from '@gorhom/bottom-sheet'
import {Theme} from '@styles/theme'
import {useSafeAreaInsets} from 'react-native-safe-area-context'
import {Subject} from 'rxjs'

import styles, {sheetContentPadding} from './index.styled'

interface BottomSheetEvent {
  action: 'open' | 'close'
  content?: ReactNode
}

export const BottomSheetSubject$ = new Subject<BottomSheetEvent>()

export const openGlobalBottomSheet = (content: ReactNode) => {
  // An open keyboard (e.g. from a search bar) would overlap the sheet
  Keyboard.dismiss()
  BottomSheetSubject$.next({
    action: 'open',
    content
  })
}

export const closeGlobalBottomSheet = () => {
  BottomSheetSubject$.next({action: 'close'})
}

const GlobalBottomSheet = () => {
  const sheetRef = useRef<BottomSheet>(null)
  const insets = useSafeAreaInsets()

  const [content, setContent] = useState<ReactNode>(null)
  const [isOpen, setIsOpen] = useState(false)

  useEffect(() => {
    const sub = BottomSheetSubject$.subscribe(({action, content}) => {
      if (action === 'open') {
        setContent(content || null)
        sheetRef.current?.expand()
        setIsOpen(true)
      } else {
        setIsOpen(false)
        setContent(null)
        sheetRef.current?.close()
      }
    })

    return () => sub.unsubscribe()
  }, [])

  return (
    <>
      {isOpen && (
        <View style={styles.backdrop}>
          <TouchableWithoutFeedback onPress={closeGlobalBottomSheet}>
            <View style={styles.backdropTouchableArea} />
          </TouchableWithoutFeedback>
        </View>
      )}

      <BottomSheet
        ref={sheetRef}
        index={-1}
        enableDynamicSizing
        enablePanDownToClose
        handleIndicatorStyle={{backgroundColor: Theme.colors.white}}
        backgroundStyle={{backgroundColor: Theme.colors.background}}
        style={styles.sheetShadow}
        onClose={closeGlobalBottomSheet}>
        <BottomSheetView style={[styles.sheetContent, sheetContentPadding(insets.bottom)]}>{content}</BottomSheetView>
      </BottomSheet>
    </>
  )
}

export default GlobalBottomSheet

import {isVersionGreaterOrEqual} from '../index.util'

describe('isVersionGreaterOrEqual', () => {
  test('returns false when version is less', () => {
    expect(isVersionGreaterOrEqual('1.4.3', '1.5.0')).toBe(false)
  })

  test('returns true when version is equal', () => {
    expect(isVersionGreaterOrEqual('1.5.0', '1.5.0')).toBe(true)
  })

  test('returns true when version is greater', () => {
    expect(isVersionGreaterOrEqual('1.6.0', '1.5.0')).toBe(true)
  })

  test('returns true when version has fewer segments but is effectively equal', () => {
    expect(isVersionGreaterOrEqual('1.5', '1.5.0')).toBe(true)
  })

  test('returns false when major version is less regardless of minor/patch', () => {
    expect(isVersionGreaterOrEqual('0.9.9', '1.0.0')).toBe(false)
  })

  test('returns true when major version is higher', () => {
    expect(isVersionGreaterOrEqual('44.4.5', '43.9.9')).toBe(true)
  })

  test('returns false when minor version is lower', () => {
    expect(isVersionGreaterOrEqual('44.3.5', '44.4.0')).toBe(false)
  })

  test('returns true when patch version is higher', () => {
    expect(isVersionGreaterOrEqual('44.4.5', '44.4.4')).toBe(true)
  })

  test('returns true when versions are equal with extra zeros', () => {
    expect(isVersionGreaterOrEqual('44.4.5.0', '44.4.5')).toBe(true)
  })

  test('returns false when major version is lower even if minor/patch are higher', () => {
    expect(isVersionGreaterOrEqual('43.10.10', '44.0.0')).toBe(false)
  })

  test('returns true when versions are exactly the same', () => {
    expect(isVersionGreaterOrEqual('44.4.5', '44.4.5')).toBe(true)
  })

  test('returns true when versions are exactly the same', () => {
    expect(isVersionGreaterOrEqual('44.4.5', '44.4.5')).toBe(true)
  })

  test('returns false when version has non-numeric parts and is less', () => {
    expect(isVersionGreaterOrEqual('1.beta.0', '1.0.1')).toBe(false)
  })

  test('returns false when version is empty', () => {
    expect(isVersionGreaterOrEqual('', '1.0.0')).toBe(false)
  })

  test('returns true when single digit version is equal', () => {
    expect(isVersionGreaterOrEqual('1', '1')).toBe(true)
  })

  test('returns false when single digit version is less', () => {
    expect(isVersionGreaterOrEqual('1', '2')).toBe(false)
  })

  test('returns true when single digit version is greater', () => {
    expect(isVersionGreaterOrEqual('2', '1')).toBe(true)
  })

  test('returns false when version is completely non-numeric', () => {
    expect(isVersionGreaterOrEqual('gjfisd', '1.5.4')).toBe(false)
  })

  test('returns true when second version is empty', () => {
    expect(isVersionGreaterOrEqual('1.2.3', '')).toBe(true)
  })
})

import React, {useState} from 'react'

import {Keyboard} from 'react-native'

import DropDownPicker from 'react-native-dropdown-picker'

import {arrowIcon, dropDownContainer, pickerControl, pickerPlaceholder, pickerText, tickIcon} from './index.styled'

export interface PickerItem {
  label: string
  value: any
}

interface Props {
  width?: number
  items: PickerItem[]
  disabled?: boolean
  placeholder?: string
  initialValue?: any
  onValueSet: (value: any) => void
}

const Picker = (props: Props) => {
  const {width, items, disabled = false, placeholder, initialValue, onValueSet} = props

  const [open, setOpen] = useState(false)
  const [value, setValue] = useState(initialValue)

  const valueSet = (v: any) => {
    onValueSet(v)
    setValue(v)
  }

  return (
    <DropDownPicker
      onPress={() => Keyboard.dismiss()}
      dropDownContainerStyle={dropDownContainer(width)}
      // @ts-ignore
      arrowIconStyle={arrowIcon}
      // @ts-ignore
      tickIconStyle={tickIcon}
      textStyle={pickerText}
      placeholderStyle={pickerPlaceholder}
      style={pickerControl(width, disabled)}
      placeholder={placeholder}
      disabled={disabled}
      open={open}
      value={value}
      items={items}
      setOpen={setOpen}
      setValue={valueSet}
    />
  )
}

export default Picker

import React, {useEffect, useState} from 'react'

import {ActivityIndicator, Keyboard, TouchableOpacity, View} from 'react-native'

import {Ionicons} from '@expo/vector-icons'
import {Theme} from '@styles/theme'

import TextInput from '@components/TextInput'

import styles from './index.styled'

export {SEARCH_BAR_HEIGHT} from './index.styled'

interface Props {
  placeholder?: string
  isLoading?: boolean
  onSearchTextChanged: (text: string) => void
}

const SearchBar = (props: Props) => {
  const {onSearchTextChanged, placeholder, isLoading} = props

  const [searchText, setSearchText] = useState('')

  useEffect(() => {
    onSearchTextChanged(searchText)
  }, [searchText])

  const onCancel = () => {
    setSearchText('')
    setTimeout(() => {
      Keyboard.dismiss()
    }, 50)
  }

  return (
    <View style={styles.container}>
      <View style={styles.inputContainer}>
        <Ionicons style={styles.searchIcon} name="search" size={20} color={Theme.colors.textSecondary} />

        <TextInput
          maxLength={100}
          style={styles.input}
          value={searchText}
          onChangeText={setSearchText}
          placeholder={placeholder}
        />

        {isLoading && <ActivityIndicator size="small" color={Theme.colors.textSecondary} />}

        {searchText !== '' && (
          <TouchableOpacity style={styles.cancelButton} onPress={onCancel}>
            <Ionicons name="close" size={20} color={Theme.colors.textSecondary} />
          </TouchableOpacity>
        )}
      </View>
    </View>
  )
}

export default SearchBar

import React, {useEffect} from 'react'

import {View, StyleSheet, ViewStyle} from 'react-native'

import LinearGradient from 'react-native-linear-gradient'
import Animated, {useSharedValue, useAnimatedStyle, withTiming, withRepeat} from 'react-native-reanimated'

import styles from './index.styled'

type Props = {
  height: number
  width: number
  borderRadius?: number
  style?: ViewStyle
}

const Skeleton = ({height = 20, width = 50, borderRadius = 8, style = {}}: Props) => {
  const shimmerTranslateX = useSharedValue(-width)

  useEffect(() => {
    shimmerTranslateX.value = withRepeat(withTiming(width, {duration: 750}), -1, false)
  }, [])

  const shimmerStyle = useAnimatedStyle(() => ({
    transform: [{translateX: shimmerTranslateX.value}]
  })) as any

  return (
    <View
      style={[
        styles.container,
        {
          height,
          width,
          borderRadius
        },
        style
      ]}>
      <Animated.View style={[StyleSheet.absoluteFill, shimmerStyle]}>
        <LinearGradient
          colors={['transparent', 'rgba(237,243,239,0.08)', 'transparent']}
          start={{
            x: 0,
            y: 0.5
          }}
          end={{
            x: 1,
            y: 0.5
          }}
          style={[styles.gradient]}
        />
      </Animated.View>
    </View>
  )
}

export default Skeleton

