    <Path
      d="M16.4 8.5c1.5 0 2.4 1.4 2.4 3.2 0 1.4-.55 2.3-.65 3.8h-3.5c-.1-1.5-.65-2.4-.65-3.8 0-1.8.9-3.2 2.4-3.2z"
      stroke={color}
      strokeWidth={strokeWidth}
